describe('Remember Me Checkbox - Authentication', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should successfully log in and set remember me cookie when checkbox is checked', () => {
    // Intercept login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in login form
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');

    // Check remember me checkbox
    cy.get('[data-testid="remember-me-checkbox"]').click();

    // Submit login form
    cy.get('[data-testid="login-button"]').click();

    // Wait for API response
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify successful login
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome back');

    // Verify remember me cookie is set
    cy.getCookie('rememberMe').should('exist');
    cy.getCookie('rememberMe').then((cookie) => {
      expect(cookie.value).to.equal('true');
    });
  });

  it('should not set remember me cookie when checkbox is unchecked', () => {
    // Intercept login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in login form
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');

    // Verify remember me checkbox is unchecked by default
    cy.get('[data-testid="remember-me-checkbox"]').should('not.be.checked');

    // Submit login form
    cy.get('[data-testid="login-button"]').click();

    // Wait for API response
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify successful login
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');

    // Verify remember me cookie is NOT set
    cy.getCookie('rememberMe').should('not.exist');
  });
});
